//! GENERATED by `./sow ui` export from `assets/ui/demo.json` — do not edit by hand.
//! Regenerate via the UI Scene Editor; this file is overwritten on every export.

use egui::{pos2, Id, RichText};
use sow_ui_kit::theme;

pub fn render(ctx: &egui::Context) {
    let screen = ctx.content_rect();
    let panel_w = 300.0_f32;
    let panel_h = 168.0_f32;
    let top_left = pos2(
        screen.center().x - panel_w * 0.5,
        screen.center().y - panel_h * 0.5,
    );

    egui::Area::new(Id::new("ui_scene.demo.root"))
        .fixed_pos(top_left)
        .show(ctx, |ui| {
            ui.set_width(panel_w);
            theme::hud_panel_frame().show(ui, |ui| {
                ui.set_width(panel_w);
                ui.vertical_centered(|ui| {
                    ui.add_space(8.0);
                    ui.label(RichText::new("Demo Scene").size(24.0).strong().color(theme::palette::neon_cyan()));
                    ui.add_space(6.0);
                    ui.label(RichText::new("Authored as JSON · generated by ./sow ui").size(12.0).color(theme::palette::text_muted()));
                    ui.add_space(12.0);
                    let _ = ui.button(RichText::new("Continue").size(14.0).color(theme::palette::text_normal()));
                    ui.add_space(10.0);
                });
            });
        });
}
